1: //! A tiny interval store: merge overlapping ranges as they are inserted.
2: 
3: /// Half-open interval `[start, end)`.
4: pub type Span = (i64, i64);
5: 
6: /// Insert `new` into `spans` (sorted, non-overlapping), merging any it touches.
7: ///
8: /// Returns the resulting sorted, non-overlapping set.
9: pub fn insert(spans: &[Span], new: Span) -> Vec<Span> {
10:     let mut out: Vec<Span> = Vec::new();
11:     let mut cur = new;
12:     for &(s, e) in spans {
13:         if e < cur.0 || s > cur.1 {
14:             // Disjoint: keep it as-is.
15:             out.push((s, e));
16:         } else {
17:             // Overlaps the one being inserted: absorb it.
18:             cur = (cur.0.min(s), cur.1.max(e));
19:         }
20:     }
21:     out.push(cur);
22:     out.sort();
23:     out
24: }

